/**
 * Blocks hand edits to shared-content files generated by the private
 * jazzjam-workbench from its canonical content/shared.json.
 *
 * The gate catches hand edits. It deliberately does NOT verify content against
 * the workbench — this repo has no credentials for the private repo — so the
 * workbench's own `sync:check` remains the authority on content correctness.
 *
 * Shared logic with musicpracticepro's scripts/check-shared-content.js — the
 * two copies differ only in GUARDED_PATHS and these comments. A change to the
 * gate logic belongs in both.
 *
 * See SHARED_CONTENT_SPEC.md.
 */
const {execFileSync} = require('child_process');

// Single source of truth for the guarded inventory. The gate keys off paths,
// not markers, matching the app repo's gate (whose fastlane files cannot carry
// a header) — even though shared.json does carry a __generated banner key.
const GUARDED_PATHS = [
  'src/_data/shared.json',
];

// The escape hatch for legitimately regenerated output. The breaking form is
// accepted because a shared-data shape change needs it.
const SYNC_SUBJECT = /^chore\(sync\)!?:/;

function git(repoDir, args) {
  return execFileSync('git', args, {
    cwd: repoDir,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

/**
 * @returns {{ok: boolean, errors: string[], violations: Array<{file: string, sha: string, shortSha: string, subject: string}>, inspected: number}}
 */
function checkSharedContent({repoDir, baseRef, headSha, guarded = GUARDED_PATHS}) {
  const errors = [];
  const violations = [];

  // baseRef must be the LIVE base branch (e.g. origin/main), not the base.sha
  // recorded in the PR event. Taking a merge base against a stale recorded sha
  // does not help: if the branch has since merged main in, the merge base IS
  // that stale commit, and mainline commits stay inside the range.
  for (const [label, rev] of [
    ['base', baseRef],
    ['head', headSha],
  ]) {
    try {
      git(repoDir, ['rev-parse', '--verify', `${rev}^{commit}`]);
    } catch {
      errors.push(`Cannot resolve ${label} revision "${rev}". Refusing to pass without a verifiable range.`);
    }
  }
  if (errors.length > 0) {
    return {ok: false, errors, violations, inspected: 0};
  }

  // A renamed or removed sync target would otherwise drift silently, because
  // `git log -- <nonexistent>` exits 0 with no output.
  for (const file of guarded) {
    try {
      git(repoDir, ['ls-files', '--error-unmatch', '--', file]);
    } catch {
      errors.push(`Guarded path "${file}" is not tracked in this repo. Update GUARDED_PATHS in scripts/check-shared-content.js.`);
    }
  }
  if (errors.length > 0) {
    return {ok: false, errors, violations, inspected: 0};
  }

  // Three-dot semantics: only commits unique to the PR branch. A branch that
  // merges main in would otherwise drag mainline commits into the range and be
  // false-failed for commits its author never wrote — and the only escapes
  // would be rewriting shared history or fabricating a chore(sync): commit,
  // the exact laundering this gate forbids.
  let mergeBase;
  try {
    mergeBase = git(repoDir, ['merge-base', baseRef, headSha]).trim();
  } catch {
    errors.push(`Cannot compute a merge base for ${baseRef}...${headSha}. Refusing to pass without a verifiable range.`);
    return {ok: false, errors, violations, inspected: 0};
  }

  // One traversal: subject plus the guarded files each commit touched. No
  // net-tree pre-check — an edit followed by a revert must still be inspected.
  // -c: without it, log prints no file names for merge commits, so a hand edit
  // written into a merge-conflict resolution would never be inspected. The
  // combined diff lists only files differing from ALL parents — exactly the
  // hand-resolved content — while a clean merge lists nothing.
  let log;
  try {
    log = git(repoDir, [
      'log',
      '-c',
      '--format=%x00%H%x1f%h%x1f%s',
      '--name-only',
      `${mergeBase}..${headSha}`,
      '--',
      ...guarded,
    ]);
  } catch (err) {
    errors.push(`git log failed for ${mergeBase}..${headSha}: ${err.message}`);
    return {ok: false, errors, violations, inspected: 0};
  }

  let inspected = 0;
  for (const record of log.split('\0')) {
    if (!record.trim()) {
      continue;
    }
    const [header, ...rest] = record.split('\n');
    const [sha, shortSha, subject] = header.split('\x1f');
    const files = rest.filter(line => line.trim() && guarded.includes(line.trim()));
    if (files.length === 0) {
      continue;
    }
    inspected += 1;
    if (SYNC_SUBJECT.test(subject)) {
      continue;
    }
    for (const file of files) {
      violations.push({file, sha, shortSha, subject});
    }
  }

  return {ok: violations.length === 0, errors, violations, inspected};
}

function main(argv) {
  const args = new Map();
  for (let i = 0; i < argv.length; i += 2) {
    args.set(argv[i], argv[i + 1]);
  }
  const baseRef = args.get('--base');
  const headSha = args.get('--head');
  const repoDir = args.get('--repo') || process.cwd();

  if (!baseRef || !headSha) {
    console.error('Usage: node scripts/check-shared-content.js --base <ref> --head <sha> [--repo <dir>]');
    console.error('  --base must be the LIVE base branch (e.g. origin/main), not the PR event base.sha.');
    process.exit(2);
  }

  const result = checkSharedContent({repoDir, baseRef, headSha});

  for (const error of result.errors) {
    console.error(`::error::${error}`);
  }
  for (const v of result.violations) {
    console.error(`::error file=${v.file}::${v.file} is generated and was edited by ${v.shortSha} (${v.subject})`);
  }

  if (result.violations.length > 0) {
    console.error('');
    console.error('Generated shared content was edited outside the sync flow.');
    console.error('');
    console.error('To change it: edit content/shared.json in the jazzjam-workbench,');
    console.error("run 'npm run sync' from the workbench root, then commit the");
    console.error("regenerated files here with a 'chore(sync):' subject.");
    console.error('');
    console.error('See SHARED_CONTENT_SPEC.md.');
  }

  if (!result.ok) {
    process.exit(1);
  }

  console.log(`No hand edits to generated shared content (${result.inspected} sync commit(s) inspected).`);
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports = {checkSharedContent, GUARDED_PATHS, SYNC_SUBJECT};
